const raw = $input.first().json.response || $input.first().json.text || '';
const cleaned = raw.replace(/```json|```/g, '').trim();
try {
  const parsed = JSON.parse(cleaned);
  // Carry forward normalised payload fields alongside parsed JD
  const upstream = $('Set — Normalise Payload').item.json;
  return [{ json: { ...upstream, jd_parsed: parsed } }];
} catch(e) {
  const upstream = $('Set — Normalise Payload').item.json;
  return [{ json: { ...upstream, jd_parsed: {}, parse_error: true, raw_output: raw } }];
}

const resp = $input.first().json;
const raw = resp.content?.[0]?.text || resp.text || '';
const cleaned = raw.replace(/```json|```/g, '').trim();
const upstream = $('Code — Parse Ollama JSON Output').item.json;
try {
  const parsed = JSON.parse(cleaned);
  return [{ json: { ...upstream, ...parsed } }];
} catch(e) {
  return [{ json: { ...upstream, parse_error: true, raw_score_output: raw, score: 0, match_strengths: [], skill_gaps: [], priority: 'low', apply_recommended: false } }];
}

